// canary-local/tests/figures.test.js — the figure ledger's contract, pinned.
//
// figures.json and everything beside it (the .svg pair per figure, the
// firmware header, the Swift) are GENERATED by
// canary-local/tools/figures/gen_figures.mjs from the committed CAD. These
// tests hold the system to the promises docs/design/FLEET_FIGURES.md makes,
// so a future edit can't quietly break them:
//   · one camera — every figure is projected the same way, or they stop
//     reading as one family
//   · the confidence ladder is DERIVED from evidence on disk, and the
//     evidence recorded next to each verdict actually supports it
//   · an idea can never render as a product (the honesty invariant)
//   · a figure never claims dimensions its CAD doesn't have
//   · every surface's copy is present and refers to figures that exist
//   · the whole thing is byte-reproducible, which is what makes the CI
//     drift gate meaningful
const { test } = require("node:test");
const assert = require("node:assert");
const { readFileSync, existsSync, readdirSync } = require("node:fs");
const { join } = require("node:path");
const { pathToFileURL } = require("node:url");

const ROOT = join(__dirname, "..");
const REPO = join(ROOT, "..");
const FIGDIR = join(ROOT, "figures");

const led = JSON.parse(readFileSync(join(ROOT, "devices/figures.json"), "utf8"));
const registry = JSON.parse(readFileSync(join(ROOT, "devices/registry.json"), "utf8"));
const catalog = JSON.parse(readFileSync(join(ROOT, "devices/catalog.json"), "utf8"));
const scadOfProduct = new Map(catalog.products.map((p) => [p.id, p.scad]));
const byId = new Map(led.figures.map((f) => [f.id, f]));
const led2hw = new Map(led.hardware.mapped.map((m) => [m.hardware, m]));

test("the ledger is the documented shape", () => {
  assert.ok(Array.isArray(led.figures) && led.figures.length > 0, "has figures");
  assert.match(led.generated_by, /gen_figures\.mjs$/, "names its generator");
  assert.strictEqual(led.spec, "docs/design/FLEET_FIGURES.md", "points at the spec");
  assert.deepStrictEqual(led.ladder.order, ["idea", "prototype", "confirmed", "shipping"],
    "the ladder runs worst-first, and is the only status vocabulary here");
  assert.ok(led.projector.rev >= 1, "the projector carries a revision");
});

test("one camera: every figure is drawn at the same scale and viewBox", () => {
  // The whole promise of the system is that a part and the device it goes
  // into are the same picture from the same viewpoint. Different viewBoxes
  // would silently reintroduce the per-drawing drift this replaces.
  for (const f of led.figures) {
    const svg = readFileSync(join(REPO, f.svg), "utf8");
    assert.match(svg, /viewBox="0 0 256 256"/, `${f.id} full figure is 256`);
    const glyph = readFileSync(join(REPO, f.glyph), "utf8");
    assert.match(glyph, /viewBox="0 0 64 64"/, `${f.id} glyph is 64`);
  }
});

test("ids are unique, and every figure names a real device or _universal", () => {
  assert.strictEqual(byId.size, led.figures.length, "no duplicate figure ids");
  const devices = new Set(registry.devices.map((d) => d.id));
  devices.add("_universal");
  devices.add("canary-display"); // the family, for boards shared across flavors
  for (const f of led.figures) {
    assert.ok(devices.has(f.device), `${f.id} -> unknown device "${f.device}"`);
    assert.match(f.id, /^(device|part|board|tool)\./, `${f.id} has a role-prefixed id`);
    assert.strictEqual(f.id.split(".")[0], f.role === "device" ? "device" : f.role,
      `${f.id}'s prefix matches its role`);
  }
});

test("the confidence ladder is derived, and its evidence supports the verdict", () => {
  for (const f of led.figures) {
    const e = f.evidence;
    assert.ok(led.ladder.order.includes(f.confidence), `${f.id} has a ladder rung`);
    if (f.role === "board") {
      // A board is somebody else's product, so our three proofs cannot apply.
      // What must hold is that its rung is still EARNED: only a board whose
      // exact orderable part is pinned (an MPN) and whose vendor CAD is
      // committed may claim the top rung. An earlier cut forced every board
      // to `shipping` from its role alone, asserting availability the ledger
      // could not substantiate.
      const vb = e.vendor_board;
      assert.ok(vb, `${f.id} is a board and must record what we know about the part`);
      if (f.confidence === "shipping") {
        assert.ok(vb.mpn, `${f.id} claims shipping — needs a manufacturer part number`);
        assert.ok(vb.mesh_committed, `${f.id} claims shipping — needs a committed board mesh`);
      } else {
        assert.strictEqual(f.confidence, "confirmed",
          `${f.id} is a board without full evidence, so it sits at confirmed`);
      }
      continue;
    }
    if (f.confidence === "shipping") {
      assert.ok(e.committed_stls.length > 0, `${f.id} claims shipping — needs a committed STL`);
      assert.ok(e.firmware_configs.length > 0, `${f.id} claims shipping — needs a firmware config`);
      assert.ok(e.catalog_variants.some((v) => v.status === "released"),
        `${f.id} claims shipping — needs a released catalog variant`);
    }
    if (f.confidence === "idea") {
      assert.strictEqual(e.registry_kind, "concept",
        `${f.id} is an idea, so the registry must call it a concept`);
      assert.strictEqual(e.committed_stls.length, 0,
        `${f.id} is an idea but has committed CAD — it has outgrown the rung`);
    }
  }
});

test("an idea can never render as a product", () => {
  // The honesty invariant. A ghost is a dashed wireframe: no fills, no
  // shading, no contact shadow. If an idea ever picks up a fill it starts
  // looking like something you can buy, which is the exact confusion the
  // ladder exists to prevent.
  for (const f of led.figures) {
    const svg = readFileSync(join(REPO, f.svg), "utf8");
    if (f.confidence === "idea") {
      assert.ok(!/fill="#/.test(svg), `${f.id} is an idea but has solid fills`);
      assert.match(svg, /stroke-dasharray/, `${f.id} is an idea but isn't drawn dashed`);
      assert.ok(!/figure-shadow/.test(svg), `${f.id} is an idea but casts a shadow`);
    } else {
      assert.match(svg, /fill="#/, `${f.id} is built but renders as a ghost`);
    }
  }
});

test("a figure never claims dimensions its CAD doesn't have", () => {
  for (const f of led.figures) {
    assert.ok(["stl", "board-cad", "assembled-cad", "sketch"].includes(f.dims_source),
      `${f.id} declares where its mm came from`);
    if (f.dims_source === "board-cad") {
      // Read from the committed board mesh, never retyped — same contract as
      // an STL, so a re-tessellation moves the figure with it.
      const vb = f.evidence.vendor_board;
      assert.ok(vb && vb.key, `${f.id} came from a board mesh, so it must name the board`);
      assert.ok(vb.mesh_committed, `${f.id} came from a board mesh, so that mesh must be committed`);
      continue;
    }
    if (f.dims_source === "stl") {
      assert.ok(f.traced_to.length > 0, `${f.id} traces to at least one STL`);
      for (const t of f.traced_to) {
        assert.ok(existsSync(join(REPO, "docs/hardware/enclosure", t.file)),
          `${f.id} traces to ${t.file}, which must be committed`);
      }
    } else {
      assert.deepStrictEqual(f.traced_to, [], `${f.id} is sketched, so it traces to nothing`);
    }
    for (const k of ["w", "d", "h"]) {
      assert.ok(f.envelope_mm[k] > 0, `${f.id} has a real ${k}`);
    }
  }
});

test("a CAD-measured in-development figure is its assembled_dims row, and stays unprintable", () => {
  // `assembled-cad`: an in-development case with no committed STLs, measured
  // off its .scad by docs/hardware/enclosure/gen_assembled_dims.py (the
  // Watch Station). The number must be that row's, exactly — it is what a
  // manifest knob edit moves — and because nothing printable is committed
  // the ladder cannot promote it past prototype on this evidence.
  const asm = JSON.parse(readFileSync(join(REPO, "docs/hardware/enclosure/assembled_dims.json"), "utf8"));
  let checked = 0;
  for (const f of led.figures) {
    if (f.dims_source !== "assembled-cad") continue;
    const row = asm.devices[f.id];
    assert.ok(row, `${f.id} is CAD-measured, so assembled_dims.json has its row`);
    for (const k of ["w", "d", "h"]) {
      assert.strictEqual(f.envelope_mm[k], row.fig[k], `${f.id} ${k} is the measured ${row.fig[k]}`);
    }
    assert.deepStrictEqual(f.assembled.seams_fig_d, row.seams_fig_d, `${f.id} carries the measured seams`);
    assert.strictEqual(f.assembled.placement, row.placement, `${f.id} names where the seat came from`);
    assert.deepStrictEqual(f.traced_to, [], `${f.id} traces to no committed STL`);
    assert.deepStrictEqual(f.evidence.committed_stls, [], `${f.id} has nothing printable committed`);
    assert.ok(f.drift_guard, `${f.id} went through the drift guard against the measurement`);
    // One case drawn at the measured height: nothing is centered, so it
    // gets the plan tolerance, not the multi-part massing's banded one.
    assert.strictEqual(f.drift_guard.height_tol_mm, undefined,
      `${f.id} is one case, so its height is held to the plan tolerance`);
    // The ladder on this evidence: nothing printable is committed, so it is
    // prototype — unless the catalog RELEASES a variant, which by the
    // ladder's own definition ("released in the catalog; one of the three
    // proofs still missing") legitimately makes it confirmed. Never shipping.
    const released = f.evidence.catalog_variants.some((v) => v.status === "released");
    assert.strictEqual(f.confidence, released ? "confirmed" : "prototype",
      `${f.id} is ${released ? "released but unprintable" : "in development"} on its evidence`);
    // ...and that evidence is THIS case's. The figure is measured off one
    // .scad, so the only catalog variants that may speak for it are the ones
    // cut from that .scad — a sibling product's released variant under the
    // same device (the Combo is a canary-vision build; the Vision's cases are
    // released) must never promote it.
    for (const v of f.evidence.catalog_variants) {
      assert.strictEqual(scadOfProduct.get(v.product), row.scad,
        `${f.id} cites ${v.product}/${v.variant}, which is not cut from ${row.scad}`);
    }
    const ownVariants = catalog.products.filter((p) => p.scad === row.scad)
      .flatMap((p) => (p.variants || []).filter((v) => (v.device || "_universal") === f.device)
        .map((v) => `${p.id}/${v.id}`));
    assert.deepStrictEqual(f.evidence.catalog_variants.map((v) => `${v.product}/${v.variant}`).sort(),
      ownVariants.sort(), `${f.id} cites every variant cut from ${row.scad}, and only those`);
    checked++;
  }
  assert.ok(checked > 0, "the Watch Station is measured off its CAD, not sketched");
  assert.strictEqual(byId.get("device.canary-display-watch").dims_source, "assembled-cad");
  // The Combo: a canary-vision build whose device has released cases — on
  // its own evidence it is in development, so it is a prototype
  const combo = byId.get("device.canary-combo");
  assert.strictEqual(combo.dims_source, "assembled-cad", "the Combo is measured off its CAD, not sketched");
  assert.strictEqual(combo.device, "canary-vision");
  assert.ok(combo.evidence.catalog_variants.length > 0, "the Combo cites its own catalog entry");
  assert.strictEqual(combo.confidence, "prototype", "the Combo does not borrow the Vision's released cases");
});

test("a CAD-measured figure draws its face features at the case's own cut variables", async () => {
  // The Combo's lens and radome window sit off-center, at lens_x/lens_y and
  // rad_cx/rad_cy — positions its case derives from the two stacks. They are
  // re-evaluated with the envelope (features_fig_mm: a center on the measured
  // envelope and an extent), so the massing must draw each exactly there, at
  // exactly that size, and MOVE when the record moves (no literal standing in).
  const { FIGURES } = await import("../tools/figures/massing.mjs");
  const asm = JSON.parse(readFileSync(join(REPO, "docs/hardware/enclosure/assembled_dims.json"), "utf8"));
  const near = (a, b) => Math.abs(a - b) < 1e-9;
  const footprint = (s) => (s.kind === "box"
    ? { x: s.at[0] + s.size[0] / 2, z: s.at[2] + s.size[2] / 2, w: s.size[0], h: s.size[2] }
    : { x: s.at[0], z: s.at[2], w: 2 * s.r, h: 2 * s.r });
  const drawnAt = (fig, row, features) => fig
    .build({ ...row.fig }, {}, { seams: row.seams_fig_d, face: row.face_fig_mm, features })
    .map(footprint);
  let checked = 0;
  for (const fig of FIGURES) {
    const row = fig.assembled ? asm.devices[fig.id] : null;
    if (!row || !row.features_fig_mm) continue;
    const shifted = Object.fromEntries(Object.entries(row.features_fig_mm)
      .map(([k, f]) => [k, { ...f, x: f.x + 1, z: f.z - 1 }]));
    for (const [features, why] of [[row.features_fig_mm, "measured"], [shifted, "moved"]]) {
      const drawn = drawnAt(fig, row, features);
      for (const [name, f] of Object.entries(features)) {
        const hits = drawn.filter((d) => near(d.x, f.x) && near(d.z, f.z) && near(d.w, f.w) && near(d.h, f.h));
        assert.strictEqual(hits.length, 1,
          `${fig.id} draws its ${name} once, ${f.w} x ${f.h} at (${f.x}, ${f.z}) — the ${why} feature`);
      }
    }
    checked++;
  }
  assert.ok(checked >= 1, "the Combo draws its lens and radome from the measured features");
});

test("a CAD-measured figure draws its glass in the CAD's measured face aperture", async () => {
  // The Dash's view-window inset used to be a literal 8.4 and the Watch's
  // glass radius E.w / 2 - 4.8 — numbers the case files derive (view_l =
  // panel_l - 2 * bez_lip; bez_ap_d) retyped where no gate could see them
  // move. gen_assembled_dims.py now measures the aperture with the envelope
  // (face_fig_mm); the massing must draw the glass in exactly that window,
  // centered, and must MOVE when it moves (so no literal is standing in).
  const { FIGURES } = await import("../tools/figures/massing.mjs");
  const asm = JSON.parse(readFileSync(join(REPO, "docs/hardware/enclosure/assembled_dims.json"), "utf8"));
  const glassOf = (fig, row, face) => {
    const E = { ...row.fig };
    const g = fig.build(E, {}, { seams: row.seams_fig_d, face }).filter((s) => s.m === "glass");
    assert.strictEqual(g.length, 1, `${fig.id} draws one glass`);
    const s = g[0];
    return s.kind === "cyl"
      ? { w: 2 * s.r, h: 2 * s.r, cx: s.at[0], cz: s.at[2], E }
      : { w: s.size[0], h: s.size[2], cx: s.at[0] + s.size[0] / 2, cz: s.at[2] + s.size[2] / 2, E };
  };
  let checked = 0;
  for (const fig of FIGURES) {
    const row = fig.assembled ? asm.devices[fig.id] : null;
    if (!row || !row.face_fig_mm) continue;
    const face = row.face_fig_mm;
    const g = glassOf(fig, row, face);
    const near = (a, b) => Math.abs(a - b) < 1e-9;
    assert.ok(near(g.w, face.w) && near(g.h, face.h),
      `${fig.id} glass ${g.w} x ${g.h} is the measured aperture ${face.w} x ${face.h}`);
    assert.ok(near(g.cx, g.E.w / 2) && near(g.cz, g.E.h / 2), `${fig.id} glass is centered as the CAD cuts it`);
    const moved = glassOf(fig, row, { w: face.w - 2, h: face.h - 2 });
    assert.ok(near(moved.w, face.w - 2) && near(moved.h, face.h - 2),
      `${fig.id} glass follows the measured aperture, not a literal`);
    checked++;
  }
  assert.ok(checked >= 2, "the Watch and the Dash draw their glass from the measured aperture");
});

test("a board figure fills the CAD box it says it came from", () => {
  // The drift guard used to skip this path entirely, so `board.xiao` shipped
  // 22.64 x 3.66 x 19.38 while its dims_source claimed CAD measuring
  // 22.64 x 4.42 x 17.78 — short in depth, over in height. A figure that
  // names its source must match it.
  const boards = JSON.parse(readFileSync(join(ROOT, "devices/boards.json"), "utf8")).boards;
  let checked = 0;
  for (const f of led.figures) {
    if (f.dims_source !== "board-cad") continue;
    const src = boards[f.evidence.vendor_board.key];
    assert.ok(src, `${f.id} names a board that is in boards.json`);
    assert.ok(f.drift_guard, `${f.id} records the tolerance it was checked against`);
    const [w, d, h] = src.dims_mm;
    assert.ok(Math.abs(f.envelope_mm.w - w) <= f.drift_guard.plan_tol_mm,
      `${f.id} width ${f.envelope_mm.w} vs CAD ${w}`);
    assert.ok(Math.abs(f.envelope_mm.h - h) <= f.drift_guard.plan_tol_mm,
      `${f.id} height ${f.envelope_mm.h} vs CAD ${h}`);
    assert.ok(f.envelope_mm.d >= d - f.drift_guard.plan_tol_mm
      && f.envelope_mm.d - d <= f.drift_guard.depth_tol_mm,
      `${f.id} depth ${f.envelope_mm.d} vs CAD ${d}`);
    checked++;
  }
  assert.ok(checked > 0, "there are board-backed figures to check");
});

test("a single-part figure fills its part's bounding box", () => {
  // The drift guard, asserted from the outside: the generator refuses to
  // emit a figure whose massing has parted company with the STL, and this
  // proves the committed output actually went through that check.
  for (const f of led.figures) {
    if (f.dims_source !== "stl" || f.traced_to.length !== 1) continue;
    assert.ok(f.drift_guard, `${f.id} records the tolerance it was checked against`);
    const [w, , h] = f.traced_to[0].mm; // SCAD frame: x, z-depth, y-height
    const stlH = f.traced_to[0].mm[1];
    assert.ok(Math.abs(f.envelope_mm.w - w) <= f.drift_guard.plan_tol_mm,
      `${f.id} width ${f.envelope_mm.w} vs part ${w}`);
    assert.ok(Math.abs(f.envelope_mm.h - stlH) <= f.drift_guard.plan_tol_mm,
      `${f.id} height ${f.envelope_mm.h} vs part ${stlH}`);
    assert.ok(h >= 0);
  }
});

test("every figure's two SVGs exist, and no orphans are left behind", () => {
  const want = new Set();
  for (const f of led.figures) {
    want.add(`${f.id}.svg`);
    want.add(`${f.id}.glyph.svg`);
    assert.ok(existsSync(join(REPO, f.svg)), `${f.svg} exists`);
    assert.ok(existsSync(join(REPO, f.glyph)), `${f.glyph} exists`);
  }
  for (const file of readdirSync(FIGDIR)) {
    assert.ok(want.has(file), `canary-local/figures/${file} is an orphan — regenerate`);
  }
  assert.strictEqual(readdirSync(FIGDIR).length, want.size, "one pair per figure, no more");
});

test("a device type is never guessed onto the wrong hardware", () => {
  // The bug this pins: `canary-nightstand` (rectangular 1.47"/1.69" boards)
  // and `canary-nightstand7` (a 7" panel) were both matched by a regex onto
  // the round 52 mm Watch Station figure. Showing someone the wrong physical
  // device is the exact failure the figures exist to prevent, so a type that
  // cannot be pinned to ONE board is omitted and recorded, never resolved by
  // a coin flip.
  const dt = led.device_types;
  assert.ok(dt, "the ledger records how running devices resolve to figures");

  const mappedTypes = new Set(dt.mapped.map((m) => m.device_type));
  for (const u of dt.unmapped) {
    assert.ok(!mappedTypes.has(u.device_type),
      `${u.device_type} cannot be both mapped and unmapped`);
    assert.ok(u.why && u.why.length > 10, `${u.device_type} says WHY it is unresolved`);
  }
  assert.ok(!mappedTypes.has("canary-nightstand"),
    "canary-nightstand must not resolve — three boards publish it with three different figures");
  // canary-nightstand7 is the counter-case: ONE board (the 7" panel) and one
  // flavor publish it, so it resolves — to the 7" slab it physically is, the
  // figure it shares with the Dash 7. This is an explicit CONFIG_FIGURE row,
  // not the regex guess this test was written against; the SHAPE is the
  // figure's claim, and the product name stays with the device type.
  const n7 = dt.mapped.find((m) => m.device_type === "canary-nightstand7");
  assert.ok(n7, "canary-nightstand7 is published by exactly one board and must resolve");
  assert.strictEqual(n7.figure, "device.canary-display-dash7",
    "canary-nightstand7 draws the 7\" slab it runs on");
  // Every mapped type points at a real, whole-device figure.
  for (const m of dt.mapped) {
    const f = byId.get(m.figure);
    assert.ok(f, `${m.device_type} -> unknown figure ${m.figure}`);
    assert.strictEqual(f.role, "device", `${m.device_type} points at a whole device`);
  }
  // The config-level mapping is kept for auditing only, and each entry must
  // still point at a real config and a real figure.
  const seen = new Set();
  for (const fl of dt.configs_audit) {
    const key = `${fl.family}/${fl.flavor}`;
    assert.ok(!seen.has(key), `${key} appears once`);
    seen.add(key);
    assert.ok(byId.get(fl.figure), `${key} -> unknown figure ${fl.figure}`);
    if (fl.source) {
      // a tree that reads no configs/ directory names the file it was read from
      assert.ok(existsSync(join(REPO, fl.source)), `${key}: ${fl.source} exists`);
      assert.ok(readFileSync(join(REPO, fl.source), "utf8").includes(`"${fl.device_type}"`),
        `${key}: ${fl.source} publishes "${fl.device_type}"`);
    } else {
      assert.ok(existsSync(join(REPO, "firmware/configs", fl.family, fl.flavor, "config.h")),
        `${key} is a real firmware config`);
    }
  }
  // A type is mappable only when every config publishing it agrees.
  const byType = new Map();
  for (const fl of dt.configs_audit) {
    if (!byType.has(fl.device_type)) byType.set(fl.device_type, new Set());
    byType.get(fl.device_type).add(fl.figure);
  }
  for (const m of dt.mapped) {
    assert.strictEqual(byType.get(m.device_type).size, 1,
      `${m.device_type} is only mapped because its configs agree`);
  }
});

test("the WAP resolves by the device type it puts on the fleet's wire, read from its sketch", async () => {
  // Sweep F258: the WAP's rows came from firmware/configs/canary-wap/, which no
  // build compiles, as "canary_wap" and "canary_wap_mobile" — types nothing
  // publishes. The glass's figure_for() compares exactly, so a WAP peer (whose
  // MQTT status says "canary-wap") never resolved on a display. The sketch
  // advertises its type twice on the wire, and both must say the same thing:
  // the mDNS `dt` record the phone keys on, and the device_type its status
  // topic carries. Since F294 its DEVICE_TYPE constant must say it too.
  // gen_figures.mjs reads it through wire_types.mjs, which reads every site
  // and refuses one it cannot spell (the next test holds the refusals).
  const WAP = join(REPO, "firmware/projects/canary-wap/arduino/canary_wap");
  const ino = readFileSync(join(WAP, "canary_wap.ino"), "utf8");
  const { walkTrees } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const [tree] = walkTrees(REPO);
  assert.strictEqual(tree.family, "canary-wap");
  for (const f of ["canary_wap.ino", "csi_mqtt.cpp"]) {
    assert.ok(tree.sites.some((s) => s.startsWith(`firmware/projects/canary-wap/arduino/canary_wap/${f}:`)),
      `${f} publishes the wire type (${tree.sites.join(", ")})`);
  }
  const wire = [tree.device_type];
  assert.deepStrictEqual(wire, ["canary-wap"], "one wire type, everywhere the sketch puts it");
  const dt = led.device_types;
  const row = dt.mapped.find((m) => m.device_type === wire[0]);
  assert.ok(row, `${wire[0]} resolves`);
  assert.strictEqual(row.figure, "device.canary-wap");
  for (const dead of ["canary_wap", "canary_wap_mobile"]) {
    assert.ok(!dt.mapped.some((m) => m.device_type === dead), `${dead}: nothing publishes it`);
  }
  // ...and the glass's table carries that exact spelling (figure_streq does not
  // canonicalize, unlike the phone's lookup).
  const h = readFileSync(join(REPO, "firmware/common/core/fleet_figures.h"), "utf8");
  assert.match(h, /\{ "canary-wap", "device\.canary-wap", "[0-9a-f]{8}", "shipping" \},/);
  // Sweep F294: the sketch's DEVICE_TYPE constant (REST /api/status,
  // node_status.node, /api/fleet's product, the boot banner, the hashed BOOT
  // attestation) is the wire type too, and it is one of the agreeing sites:
  // the reader reads its declaration line.
  assert.match(ino, /^static const char\* DEVICE_TYPE\s*=\s*"canary-wap";/m);
  const declLine = ino.slice(0, ino.search(/^static const char\* DEVICE_TYPE\s*=/m)).split("\n").length;
  assert.ok(tree.sites.includes(`firmware/projects/canary-wap/arduino/canary_wap/canary_wap.ino:${declLine}`),
    `the DEVICE_TYPE declaration at canary_wap.ino:${declLine} is a read site (${tree.sites.join(", ")})`);
  // Every surface that is not an mDNS or MQTT wire site reads the constant
  // rather than a literal of its own, which the reader would not see (it reads
  // the constant, not them): REST /api/status's device_type and its
  // node_status.node, /api/fleet's self.product, the hashed BOOT attestation's
  // device_type and the boot banner's Type line. The mDNS dt records stay
  // literals, which the reader requires of them; so do csi_mqtt.cpp's status
  // strings. Read with comments blanked, so a commented-out line is no reader.
  const { codeOnly } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const inoCode = codeOnly(ino);
  const readers = [
    ["REST /api/status's device_type", /^\s*doc\["device_type"\]\s*=\s*DEVICE_TYPE;/m,
      /^\s*doc\["device_type"\]\s*=\s*"/m],
    ["node_status.node", /^\s*ns\.node\s*=\s*DEVICE_TYPE;/m, /^\s*ns\.node\s*=\s*"/m],
    ["/api/fleet's product", /^\s*self\.product\s*=\s*DEVICE_TYPE;/m, /^\s*self\.product\s*=\s*"/m],
    ["the BOOT attestation's device_type", /w\.write_text\("device_type"\);\s*w\.write_text\(DEVICE_TYPE\);/,
      /w\.write_text\("device_type"\);\s*w\.write_text\("/],
    ["the boot banner's Type line", /^\s*bi\.device_type\s*=\s*DEVICE_TYPE;/m, /^\s*bi\.device_type\s*=\s*"/m],
  ];
  for (const [what, reads, literal] of readers) {
    assert.strictEqual((inoCode.match(new RegExp(reads.source, "gm")) || []).length, 1, `${what} reads DEVICE_TYPE, once`);
    assert.ok(!literal.test(inoCode), `${what} is not handed a literal anywhere in the sketch`);
  }
  // "canary" is the flagship tree's word (firmware/canary) and is not mapped to the WAP.
  assert.ok(!dt.mapped.some((m) => m.device_type === "canary"), "\"canary\" is not mapped to the WAP");
  // The WAP figure's firmware evidence is the flavor the Workshop publishes
  // from the same sketch (gen_enclosures.py), so its confidence stays derived.
  const ws = JSON.parse(readFileSync(join(ROOT, "devices/workshop.json"), "utf8"));
  assert.deepStrictEqual(byId.get("device.canary-wap").evidence.firmware_configs,
    Object.keys(ws.devices["canary-wap"].firmware.flavors));
  assert.strictEqual(byId.get("device.canary-wap").confidence, "shipping");
});

test("the WAP's wire-type reader refuses every site it cannot spell, not only a file with none", async () => {
  // Sweep F258 review: the first reader matched only the literal shape, so a
  // dt record handed a variable beside two literal ones passed --check. Each
  // case is a copy of the real sketch files with one edit, read under a
  // scratch root.
  const os = require("node:os");
  const fs = require("node:fs");
  const { walkTrees, TREE_TYPES } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const [row] = TREE_TYPES;
  const [inoF, mqttF] = row.sources.map((s) => s.file);
  const real = { [inoF]: readFileSync(join(REPO, inoF), "utf8"), [mqttF]: readFileSync(join(REPO, mqttF), "utf8") };
  const DT = 'MDNS.addServiceTxt("securacv", "tcp", "dt",   "canary-wap");';
  const STATUS = 'const char* online = "{\\"online\\":true,\\"device_type\\":\\"canary-wap\\"}";';
  // Sweep F294: the DEVICE_TYPE constant is the third source, read from the
  // same .ino; BANNER is one of its readers, inside setup().
  const CONST = 'static const char* DEVICE_TYPE        = "canary-wap";';
  const BANNER = '    bi.device_type   = DEVICE_TYPE;';
  assert.strictEqual(row.sources[2].file, inoF, "the constant is read from the sketch's .ino");
  assert.strictEqual(real[inoF].split(DT).length - 1, 3, "the fixture edits find the three dt records");
  assert.ok(real[mqttF].includes(STATUS), "the fixture edits find the online status");
  assert.strictEqual(real[inoF].split(CONST).length - 1, 1, "the fixture edits find the one DEVICE_TYPE declaration");
  assert.strictEqual(real[inoF].split(BANNER).length - 1, 1, "the fixture edits find the boot banner's read of it");
  const inSetup = (r, line) => ({ [inoF]: r[inoF].replace(BANNER, `    ${line}\n${BANNER}`) });
  const second = (text, from, to) => { const i = text.indexOf(from, text.indexOf(from) + 1); return text.slice(0, i) + to + text.slice(i + from.length); };
  const dir = fs.mkdtempSync(join(os.tmpdir(), "securacv-wire-types-"));
  const readWith = (edit) => {
    const files = { ...real, ...edit(real) };
    for (const [f, text] of Object.entries(files)) {
      fs.mkdirSync(join(dir, f, ".."), { recursive: true });
      fs.writeFileSync(join(dir, f), text);
    }
    return walkTrees(dir);
  };
  try {
    assert.strictEqual(readWith(() => ({}))[0].device_type, "canary-wap", "the unedited copy reads");
    const refusals = [
      ["one dt record handed a variable beside two literals",
        (r) => ({ [inoF]: second(r[inoF], DT, 'MDNS.addServiceTxt("securacv", "tcp", "dt",   WAP_DT);') }), /canary_wap\.ino:\d+: the "dt" value is not one string literal \(WAP_DT\)/],
      ["a dt record handed DEVICE_TYPE",
        (r) => ({ [inoF]: second(r[inoF], DT, 'MDNS.addServiceTxt("securacv", "tcp", "dt", DEVICE_TYPE);') }), /not one string literal \(DEVICE_TYPE\)/],
      ["a dt value built by concatenation",
        (r) => ({ [inoF]: second(r[inoF], DT, 'MDNS.addServiceTxt("securacv", "tcp", "dt", "canary" "-wap");') }), /not one string literal/],
      ["a TXT key this reader cannot read",
        (r) => ({ [inoF]: second(r[inoF], DT, 'MDNS.addServiceTxt("securacv", "tcp", kDtKey, "canary-wap");') }), /key that is not one string literal \(kDtKey\)/],
      ["a status built around a %s",
        (r) => ({ [mqttF]: r[mqttF].replace(STATUS, 'const char* online = "{\\"online\\":true,\\"device_type\\":\\"%s\\"}";') }), /csi_mqtt\.cpp:\d+: "device_type" is not the key of a literal value/],
      ["a status that ends its string at the key",
        (r) => ({ [mqttF]: r[mqttF].replace(STATUS, 'const char* online = "{\\"online\\":true,\\"device_type\\":\\"" DEVICE_TYPE "\\"}";') }), /csi_mqtt\.cpp:\d+: "device_type" is not the key/],
      ["an ArduinoJson device_type",
        (r) => ({ [mqttF]: r[mqttF].replace(STATUS, 'doc["device_type"] = DEVICE_TYPE;') }), /"device_type" is not the key of a literal value/],
      ["two literals that disagree",
        (r) => ({ [inoF]: second(r[inoF], DT, 'MDNS.addServiceTxt("securacv", "tcp", "dt", "canary-wapx");') }), /publishes 2 different device types/],
      ["a file with no site left",
        (r) => ({ [mqttF]: r[mqttF].split("device_type").join("dev_kind") }), /csi_mqtt\.cpp no longer publishes/],
      // Sweep F294: the constant agrees with the wire sites, is declared once
      // with one literal, and no other assignment names it (=, a compound
      // assignment, ++ or --, prefix or postfix).
      ["the constant set back to the flagship's word",
        (r) => ({ [inoF]: r[inoF].replace(CONST, 'static const char* DEVICE_TYPE        = "canary";') }),
        /publishes 2 different device types[\s\S]*"canary" at [^;]*canary_wap\.ino:\d+/],
      ["the constant handed a name",
        (r) => ({ [inoF]: r[inoF].replace(CONST, 'static const char* DEVICE_TYPE        = WAP_TYPE;') }),
        /canary_wap\.ino:\d+: DEVICE_TYPE is not one string literal \(WAP_TYPE\)/],
      ["a second declaration of the constant",
        (r) => ({ [inoF]: r[inoF].replace(CONST, `${CONST}\nstatic const char* DEVICE_TYPE = "canary-wap";`) }),
        /DEVICE_TYPE is declared 2 times/],
      ["the constant repointed at run time",
        (r) => inSetup(r, 'DEVICE_TYPE = "canary";'), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      ["the constant moved by a compound assignment",
        (r) => inSetup(r, "DEVICE_TYPE += 7;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      // `-=` is the other compound operator a pointer takes.
      ["the constant moved by a compound subtraction",
        (r) => inSetup(r, "DEVICE_TYPE -= 1;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      ["the constant moved by an increment",
        (r) => inSetup(r, "++DEVICE_TYPE;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      ["the constant moved by a prefix decrement",
        (r) => inSetup(r, "--DEVICE_TYPE;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      ["the constant moved by a postfix increment",
        (r) => inSetup(r, "DEVICE_TYPE++;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      ["the constant moved by a postfix decrement",
        (r) => inSetup(r, "DEVICE_TYPE--;"), /canary_wap\.ino:\d+: DEVICE_TYPE is assigned here/],
      // A flavor split spelled in the declaration (the F258 failure shape):
      // the first literal of the expression is not the type.
      ["the constant declared as a choice between two literals",
        (r) => ({ [inoF]: r[inoF].replace(CONST, 'static const char* DEVICE_TYPE        = WAP_MOBILE ? "canary-wap-mobile" : "canary-wap";') }),
        /canary_wap\.ino:\d+: DEVICE_TYPE is not one string literal \(WAP_MOBILE \? "canary-wap-mobile" : "canary-wap"\)/],
      ["the constant declared as two literals concatenated",
        (r) => ({ [inoF]: r[inoF].replace(CONST, 'static const char* DEVICE_TYPE        = "canary" "-wap";') }),
        /canary_wap\.ino:\d+: DEVICE_TYPE is not one string literal \("canary" "-wap"\)/],
      ["the constant gone",
        (r) => ({ [inoF]: r[inoF].replace(CONST, "#define DEVICE_TYPE \"canary-wap\"") }),
        /canary_wap\.ino no longer publishes canary-wap's device type as the DEVICE_TYPE constant/],
      // The const-pointer declarations are read as the declaration, not
      // refused as an assignment, so a wrong type in one is a disagreement.
      ["the const-pointer constant set back to the flagship's word",
        (r) => ({ [inoF]: r[inoF].replace(CONST, 'static const char* const DEVICE_TYPE  = "canary";') }),
        /publishes 2 different device types[\s\S]*"canary" at [^;]*canary_wap\.ino:\d+/],
    ];
    for (const [name, edit, why] of refusals) {
      assert.throws(() => readWith(edit), why, name);
    }
    // A longer name and a comparison are not writes of the constant.
    const near = readWith((r) => ({ [inoF]: r[inoF].replace(CONST, `${CONST}\nstatic const char* WAP_DEVICE_TYPE = "x";`)
      .replace(BANNER, `    if (DEVICE_TYPE == nullptr) return;\n${BANNER}`) }))[0];
    assert.strictEqual(near.device_type, "canary-wap", "WAP_DEVICE_TYPE and a == are not read as the constant");
    assert.strictEqual(near.sites.length, 6, "three dt records, two status strings, one declaration");
    // A const pointer, whose other assignments the compiler refuses too, is
    // the stronger form of the one declaration, and is read as it.
    for (const decl of ['static const char* const DEVICE_TYPE  = "canary-wap";',
      'static constexpr const char* DEVICE_TYPE = "canary-wap";']) {
      const [held] = readWith((r) => ({ [inoF]: r[inoF].replace(CONST, decl) }));
      assert.strictEqual(held.device_type, "canary-wap", `${decl} is read as the declaration`);
      assert.strictEqual(held.sites.length, 6, `${decl}: three dt records, two status strings, one declaration`);
    }
    // A commented-out site publishes nothing, so it is no site.
    assert.strictEqual(readWith((r) => ({ [inoF]: r[inoF].replace(DT, `${DT}\n  // MDNS.addServiceTxt("securacv", "tcp", "dt", DEVICE_TYPE);\n  /* doc["device_type"] = x; DEVICE_TYPE = "canary"; */`) }))[0].sites.length, 6,
      "a commented-out call is not read");
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("the exact lookup is keyed on something the build already depends on", () => {
  // A config directory is not one piece of hardware: 12 build envs resolve to
  // canary-display/dash, and dash / dash-b / dash-mic compile the 4.3, 4.3B
  // and 4.3C panels between them. The boards/<id>/pins header each env
  // compiles against IS one piece of hardware, and it is load-bearing — wrong
  // pins, dead device — so it cannot quietly drift the way a decorative
  // product tag could. That is why the exact table is keyed on it.
  const hw = led.hardware;
  assert.ok(hw && Array.isArray(hw.mapped), "the ledger carries a hardware table");
  assert.match(hw.key, /pins/, "the table says what it is keyed on");

  const seen = new Set();
  for (const m of hw.mapped) {
    assert.ok(!seen.has(m.hardware), `${m.hardware} appears once`);
    seen.add(m.hardware);
    const f = byId.get(m.figure);
    assert.ok(f, `${m.hardware} -> unknown figure ${m.figure}`);
    assert.strictEqual(f.role, "device", `${m.hardware} points at a whole device`);
    assert.ok(m.builds.length > 0, `${m.hardware} is compiled by at least one build`);
    if (m.hardware.startsWith("board:")) continue;
    // The board must name itself in the header the build compiles, or
    // my_figure() returns nullptr on a device that has a figure.
    const pins = join(REPO, "firmware/boards", m.hardware, "pins/pins.h");
    assert.ok(existsSync(pins), `${m.hardware} has a pins header`);
    assert.ok(readFileSync(pins, "utf8")
      .includes(`#define CANARY_FIGURE_HARDWARE "${m.hardware}"`),
    `${m.hardware}'s pins header declares its own figure hardware id`);
  }

  // Hardware we cannot draw is listed, not silently dropped.
  for (const u of hw.unmapped) {
    assert.ok(!seen.has(u.hardware), `${u.hardware} cannot be both mapped and unmapped`);
    assert.ok(u.builds.length > 0, `${u.hardware} names the builds it covers`);
  }
  // The 4.3B panel is the case that started all this: it must never borrow
  // the plain 4.3's figure.
  const b = hw.mapped.find((m) => m.hardware === "waveshare-esp32s3-lcd43b");
  assert.strictEqual(b, undefined,
    "the 4.3B panel has no figure of its own yet, so it must not borrow the 4.3's");
});

test("a board carrying two products says so", () => {
  // Exact about the BOARD is not the same as exact about the PRODUCT. The 7"
  // glass is compiled by both canary-display-dash7 and -nightstand7, so a
  // Nightstand 7 asking my_figure() gets a figure titled "Canary Dash 7" —
  // the right shape, the wrong name. The row has to admit that, or a caller
  // printing the title would relabel the device.
  for (const m of led.hardware.mapped) {
    assert.ok(Array.isArray(m.serves), `${m.hardware} records what it serves`);
    assert.strictEqual(m.shared, m.serves.length > 1,
      `${m.hardware}'s shared flag must follow the device types it carries`);
  }
  const seven = led.hardware.mapped.find((m) => m.hardware === "waveshare-esp32s3-lcd7");
  assert.ok(seven, "the 7-inch board resolves to a figure");
  assert.ok(seven.shared, "the 7-inch board carries two products and must be flagged");
  assert.ok(seven.serves.length > 1, `expected several device types, got ${seven.serves}`);

  // And the flag has to reach the firmware, or the C++ caller can't check it.
  const h = readFileSync(join(REPO, "firmware/common/core/fleet_figures.h"), "utf8");
  assert.match(h, /bool shared_across_products/, "the header carries the flag");
  assert.ok(!/figure_for_hardware\(id\) *EXACT/.test(h),
    "the header must not claim exactness it does not have about the product");
  const row = h.split("\n").find((l) => l.includes('"waveshare-esp32s3-lcd7"'));
  assert.ok(row && /, true \}/.test(row), `the 7-inch row must set the flag: ${row}`);
});

test("every drawn board serves the device type its builds publish", async () => {
  // `serves` is how a caller asks which product a board is when the figure's
  // title names only one. It was derived from each env's firmware/configs/
  // include, so the WAP's four envs, which build the sketch tree and include no
  // config, left board:seeed_xiao_esp32s3 serving nothing (sweep A89). The
  // sketch's row in TREE_TYPES now keys those envs, through the project whose
  // src_dir holds the row's sources, so the board serves the type the sketch
  // puts on the wire.
  for (const m of led.hardware.mapped) {
    assert.ok(m.serves.length > 0,
      `${m.hardware} is drawn and built by ${m.builds.join(", ")}, so it serves a device type`);
  }
  const { walkTrees } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const [tree] = walkTrees(REPO);
  const xiao = led2hw.get("board:seeed_xiao_esp32s3");
  assert.ok(xiao, "the WAP's board resolves to a figure");
  assert.strictEqual(xiao.figure, "device.canary-wap");
  assert.deepStrictEqual(xiao.serves, [tree.device_type],
    "the WAP's board serves the one type the sketch publishes");
  assert.ok(xiao.builds.every((b) => b.startsWith("canary-wap-")), `${xiao.builds}`);
});

test("the tree-config join keys a sketch's envs, and refuses what it cannot decide", async () => {
  // treeConfigsOfEnvs() (sweep A89) is what lets the WAP's envs, which include
  // no firmware/configs/ flavor, serve the sketch's wire type. Each refusal is
  // driven here with synthetic projects and envs, so none can rot into a guess.
  const { treeConfigsOfEnvs } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const W = "firmware/projects/w";
  const project = (name, src, files) => ({ project: `firmware/projects/${name}`, src,
    files: new Set(files) });
  const wap = project("w", `${W}/arduino/w`, [`${W}/platformio.ini`, "firmware/envs/platformio/w.ini",
    "firmware/envs/platformio/common.ini"]);
  const other = project("o", "firmware/projects/o/src", ["firmware/projects/o/platformio.ini",
    "firmware/envs/platformio/o.ini", "firmware/envs/platformio/common.ini"]);
  const row = { family: "w", flavor: "sketch",
    sources: [{ file: `${W}/arduino/w/w.ino` }, { file: `${W}/arduino/w/mqtt.cpp` }] };
  const env = (name, file, config = null) => ({ env: name, file, config });
  const envs = () => [env("w-a", "firmware/envs/platformio/w.ini"),
    env("w-b", "firmware/envs/platformio/w.ini"), env("o-a", "firmware/envs/platformio/o.ini", "o/x")];

  // The happy join: the sketch's envs take its key; another project's env keeps its config.
  const joined = treeConfigsOfEnvs(envs(), [wap, other], [row]);
  assert.deepStrictEqual(joined.map((e) => [e.env, e.config]),
    [["w-a", "w/sketch"], ["w-b", "w/sketch"], ["o-a", "o/x"]]);

  const refuses = (why, re, list, projects, rows = [row]) => assert.throws(
    () => treeConfigsOfEnvs(list, projects, rows), re, why);
  refuses("a row no project compiles", /no firmware\/projects\/<p>\/platformio\.ini src_dir compile/,
    envs(), [other]);
  refuses("a row two projects compile (a src_dir inside another)", /2 projects \(firmware\/projects\/w, firmware\/projects\/wide\)/,
    envs(), [wap, project("wide", W, [`${W}/other.ini`])]);
  refuses("a row whose sources span two projects", /no firmware\/projects\/<p>\/platformio\.ini src_dir compile/,
    envs(), [wap, other], [{ ...row, sources: [...row.sources, { file: "firmware/projects/o/src/x.cpp" }] }]);
  refuses("a row no env builds", /no env builds firmware\/projects\/w's src_dir/,
    [env("o-a", "firmware/envs/platformio/o.ini", "o/x")], [wap, other]);
  refuses("an env file two projects pull in", /env w-c is defined in firmware\/envs\/platformio\/common\.ini, which firmware\/projects\/w and firmware\/projects\/o all pull in/,
    [...envs(), env("w-c", "firmware/envs/platformio/common.ini")], [wap, other]);
  refuses("an env that also includes a configs/ flavor", /env w-b builds the w\/sketch sketch .* and includes configs\/canary\/x too/,
    [env("w-a", "firmware/envs/platformio/w.ini"), env("w-b", "firmware/envs/platformio/w.ini", "canary/x")],
    [wap, other]);
});

test("readProjects reads each project's src_dir and env files off its platformio.ini", async () => {
  const { readProjects } = await import(pathToFileURL(join(ROOT, "tools/figures/wire_types.mjs")).href);
  const { mkdtempSync, mkdirSync, writeFileSync, rmSync } = require("node:fs");
  const { tmpdir } = require("node:os");
  const root = mkdtempSync(join(tmpdir(), "figures-projects-"));
  try {
    const put = (rel, text) => {
      mkdirSync(join(root, rel, ".."), { recursive: true });
      writeFileSync(join(root, rel), text);
    };
    // Multi-line extra_configs with a comment line; a src_dir; a section after.
    put("firmware/projects/a/platformio.ini", "[platformio]\n; envs\nextra_configs =\n"
      + "    ../../envs/platformio/common.ini\n    ; a comment line\n    ../../envs/platformio/a.ini ; trailing\n"
      + "\ndefault_envs = a\nsrc_dir = arduino/a\n\n[env]\nsrc_dir = elsewhere\n");
    // One-line extra_configs, no src_dir: PlatformIO's default `src`.
    put("firmware/projects/b/platformio.ini", "[platformio]\nextra_configs = b.ini\n\n[env:b]\nboard = x\n");
    // A directory with no platformio.ini is not a project.
    put("firmware/projects/c/README.md", "not a project\n");
    const got = readProjects(root).map((p) => ({ ...p, files: [...p.files].sort() }));
    assert.deepStrictEqual(got, [
      { project: "firmware/projects/a", src: "firmware/projects/a/arduino/a",
        files: ["firmware/envs/platformio/a.ini", "firmware/envs/platformio/common.ini",
          "firmware/projects/a/platformio.ini"] },
      { project: "firmware/projects/b", src: "firmware/projects/b/src",
        files: ["firmware/projects/b/b.ini", "firmware/projects/b/platformio.ini"] },
    ]);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
  // And the tree: the WAP's project compiles its sketch and pulls in its env file.
  const wap = readProjects(REPO).find((p) => p.project === "firmware/projects/canary-wap");
  assert.strictEqual(wap.src, "firmware/projects/canary-wap/arduino/canary_wap");
  assert.ok(wap.files.has("firmware/envs/platformio/canary-wap.ini"), [...wap.files].join(", "));
});

test("nothing a figure draws falls outside the frame it declares", () => {
  // The contact shadow used to be laid out AFTER the fit, so it could land
  // outside the viewBox and be clipped — a round display shadow reached
  // y = 293.8 in a 256 box. Everything drawn has to be inside the frame.
  for (const f of led.figures) {
    for (const [path, box] of [[f.svg, 256], [f.glyph, 64]]) {
      const svg = readFileSync(join(REPO, path), "utf8");
      const nums = [...svg.matchAll(/d="([^"]+)"/g)]
        .flatMap((m) => m[1].match(/-?\d+(?:\.\d+)?/g) || [])
        .map(Number);
      assert.ok(nums.length > 0, `${path} draws something`);
      assert.ok(Math.min(...nums) >= -1, `${path} draws left/above its viewBox`);
      assert.ok(Math.max(...nums) <= box + 1, `${path} draws past its ${box} viewBox`);
    }
  }
});

test("the firmware header lets a device name its own figure", () => {
  const h = readFileSync(join(REPO, "firmware/common/core/fleet_figures.h"), "utf8");
  assert.match(h, /GENERATED by/, "says it is generated");
  assert.match(h, /namespace canary::figures/, "lands in the fleet's namespace");
  const table = (name) => {
    const body = h.slice(h.indexOf(`${name}[] = {`));
    // Hardware rows carry a trailing bool (shared_across_products); device-type
    // rows do not. Tolerate either so one helper reads both tables.
    return [...body.slice(0, body.indexOf("};"))
      .matchAll(/\{ "([^"]+)", "(device\.[^"]+)", "([0-9a-f]{8})", "([a-z]+)"(?:, (true|false))? \}/g)];
  };
  const rows = table("kFigures");
  const hwRows = table("kHardware");
  assert.ok(rows.length > 0, "has at least one device type");
  assert.strictEqual(rows.length, led.device_types.mapped.length,
    "the header carries exactly the ledger's resolvable device types");
  assert.strictEqual(hwRows.length, led.hardware.mapped.length,
    "the header carries exactly the ledger's resolvable hardware");
  assert.match(h, /figure_for_hardware/, "the exact lookup is exposed");
  assert.match(h, /CANARY_FIGURE_HARDWARE/, "a build can ask what it itself is");
  for (const [, hardware, figureId, rev] of hwRows) {
    const f = byId.get(figureId);
    assert.ok(f, `${hardware} points at unknown figure ${figureId}`);
    assert.strictEqual(f.rev, rev, `${hardware}'s rev matches the ledger`);
  }
  for (const [, deviceType, figureId, rev, confidence] of rows) {
    const f = byId.get(figureId);
    assert.ok(f, `${deviceType} points at unknown figure ${figureId}`);
    assert.strictEqual(f.rev, rev, `${deviceType}'s rev matches the ledger`);
    assert.strictEqual(f.confidence, confidence, `${deviceType}'s confidence matches the ledger`);
    assert.strictEqual(f.role, "device",
      `${deviceType} must point at a whole device, not a ${f.role}`);
  }
  // No Arduino, no JSON, no allocation — same rules fleet_model.h follows,
  // so this stays host-testable.
  assert.ok(!/#include <Arduino|ArduinoJson|malloc|new /.test(h),
    "the header stays dependency-free");
});

test("the Swift copy carries the same figures, from the same plan", () => {
  const sw = readFileSync(join(REPO, "ios/Shared/FleetFigures.swift"), "utf8");
  assert.match(sw, /GENERATED by/, "says it is generated");
  const ids = [...sw.matchAll(/^ {2}"([^"]+)": FleetFigure\($/gm)].map((m) => m[1]);
  assert.deepStrictEqual(new Set(ids), new Set(led.figures.map((f) => f.id)),
    "the phone and the wrist know exactly the figures the ledger does");
  for (const f of led.figures) {
    assert.ok(sw.includes(`rev: "${f.rev}"`), `${f.id}'s rev crossed over`);
  }
  // The ghost rule has to hold on the wrist too, or an idea would render
  // solid on one surface and dashed on another.
  const ideas = led.figures.filter((f) => f.confidence === "idea");
  assert.ok(ideas.length > 0, "there are ideas to check");
  for (const f of ideas) {
    const block = sw.slice(sw.indexOf(`"${f.id}": FleetFigure(`));
    const end = block.indexOf("]),");
    assert.ok(!/kind: \.face/.test(block.slice(0, end)),
      `${f.id} is an idea but ships filled faces to SwiftUI`);
  }
});

test("the Swift massing file carries the same fleet, ready to turn", () => {
  // FleetSolids.swift is the third Swift artifact: the mm solids behind each
  // figure, which the phone's turntable re-projects at any yaw. Its contract
  // with the ledger is the same as FleetFigures.swift's — same ids, same
  // revs — plus two of its own: every solid names a material the palette
  // defines, and the ghost verdict crosses over exactly (the honesty
  // invariant must hold at every angle, so it rides the data, not the view).
  const sw = readFileSync(join(REPO, "ios/Shared/FleetSolids.swift"), "utf8");
  assert.match(sw, /GENERATED by/, "says it is generated");

  const ids = [...sw.matchAll(/^ {2}"([^"]+)": FleetMassing\($/gm)].map((m) => m[1]);
  assert.deepStrictEqual(new Set(ids), new Set(led.figures.map((f) => f.id)),
    "the massing file knows exactly the figures the ledger does");

  const palette = new Set(
    [...sw.matchAll(/^ {4}"([a-z0-9]+)": \[[\d.]+, [\d.]+, [\d.]+\],$/gm)].map((m) => m[1]));
  assert.ok(palette.size >= 8, "the palette crossed over");
  for (const m of sw.matchAll(/material: "([a-z0-9]+)"/g)) {
    assert.ok(palette.has(m[1]), `solid names unknown material "${m[1]}"`);
  }

  for (const f of led.figures) {
    const block = sw.slice(sw.indexOf(`"${f.id}": FleetMassing(`));
    const head = block.slice(0, block.indexOf("solids:"));
    assert.ok(head.includes(`rev: "${f.rev}"`), `${f.id}'s rev crossed over`);
    assert.ok(head.includes(`ghost: ${f.confidence === "idea"}`),
      `${f.id}'s ghost verdict must match its rung`);
  }
});

test("the iPhone/Watch bridge only names figures that exist", () => {
  // FleetFigureBridge.swift is the ONE hand-written piece on the Apple side —
  // the judgment that maps a decoded DeviceType onto a figure. Swift compiles
  // on the mac runners, but a bad figure id there is a runtime nil, not a
  // build error, so it gets checked here too where it costs nothing.
  const bridge = readFileSync(join(REPO, "ios/Shared/FleetFigureBridge.swift"), "utf8");
  const named = [...bridge.matchAll(/return "(device\.[^"]+)"/g)].map((m) => m[1]);
  assert.ok(named.length > 0, "the bridge names at least one figure");
  for (const id of named) {
    assert.ok(byId.get(id), `the Apple bridge names "${id}", which is not a figure`);
    assert.strictEqual(byId.get(id).role, "device", `${id} is a whole device`);
  }
  // The display family collapses four products into one enum case, so it must
  // stay nil — the same rule the firmware table keeps for canary-dash. (The
  // nightlight once rode the same nil; its figure — the C3 pocket case — now
  // comes through the pipeline, so its case names it above.)
  assert.match(bridge, /case \.display, \.unknown: return nil/,
    "the display family must not be given a figure it would have to guess at");
  assert.match(bridge, /case \.nightlight: return "device\.canary-nightlight"/,
    "the nightlight resolves to its own figure, not a borrowed sibling shape");

  // And the rows actually draw it, or none of this reaches a user.
  const fleetView = readFileSync(join(REPO, "ios/Sources/SecuraCV/Views/FleetView.swift"), "utf8");
  assert.match(fleetView, /DeviceFigureIcon\(witness\.deviceType/,
    "the witness roster draws the device's figure");
  assert.match(fleetView, /DeviceFigureIcon\(canary\.deviceType/,
    "the discovered-device row draws it too");
});

test("the flasher picker draws a board only when it can prove which one", () => {
  // The picker is where a wrong picture costs the most: somebody is holding a
  // board and matching it against the row. So a figure appears only when the
  // catalog can point at WHY — either the pins header the build compiles (the
  // same load-bearing declaration the firmware lookup uses) or an explicit
  // declaration in the product table, checked against the ledger.
  const flash = JSON.parse(readFileSync(join(ROOT, "devices/flash.json"), "utf8"));
  const picker = JSON.parse(readFileSync(join(ROOT, "devices/figures.picker.json"), "utf8"));
  let drawn = 0;
  for (const p of flash.products) {
    const f = p.figure;
    if (!f) continue;                       // placeholder — always allowed
    drawn++;
    const led = byId.get(f.id);
    assert.ok(led, `${p.id} draws "${f.id}", which is not a figure`);
    assert.strictEqual(led.role, "device", `${p.id} draws a whole device`);
    assert.strictEqual(f.title, led.title, `${p.id}'s caption matches the ledger`);
    assert.ok(f.via, `${p.id} records how its figure was resolved`);
    assert.strictEqual(f.svg, picker.figures[f.id],
      `${p.id} carries the generated picker SVG verbatim`);
    if (f.hardware) {
      const hw = led2hw.get(f.hardware);
      assert.ok(hw, `${p.id} names hardware "${f.hardware}" that has no figure`);
      assert.strictEqual(hw.figure, f.id, `${p.id}'s hardware and figure agree`);
      assert.strictEqual(!!f.shared, !!hw.shared, `${p.id} carries the shared flag through`);
    } else {
      assert.match(f.via, /declared/, `${p.id} has no hardware, so it must say it was declared`);
    }
  }
  assert.ok(drawn > 0, "some rows draw a figure");
});

test("both flashers render the slot, and neither invents a product", () => {
  // The two flashers share no UI code (AGENTS.md rule 7), so this is the only
  // thing standing between them and drift. Both must render the slot, and
  // both must fall back to the SAME neutral placeholder — a plausible generic
  // board would be worse than nothing, because it is matchable.
  const browser = readFileSync(join(ROOT, "assets/flash.js"), "utf8");
  const desktop = readFileSync(join(REPO, "desktop/src/app.js"), "utf8");
  for (const [name, src] of [["browser", browser], ["desktop", desktop]]) {
    assert.match(src, /figureSlot\(/, `the ${name} flasher builds a figure slot`);
    assert.match(src, /placeholder/, `the ${name} flasher has a placeholder state`);
    assert.match(src, /is also (built|sold) as another product/,
      `the ${name} flasher says when one board is two products`);
  }
  for (const [name, css] of [
    ["browser", readFileSync(join(ROOT, "assets/flash.css"), "utf8")],
    ["desktop", readFileSync(join(REPO, "desktop/src/styles.css"), "utf8")],
  ]) {
    // Same fixed size in both, which is what makes the list stop reflowing as
    // figures arrive.
    assert.match(css, /width: 46px;\s*\n?\s*height: 46px|width: 46px; height: 46px/,
      `the ${name} flasher's slot is a fixed 46px`);
  }
});

test("the ledger counts what it says it counts", () => {
  for (const rung of led.ladder.order) {
    const n = led.figures.filter((f) => f.confidence === rung).length;
    assert.strictEqual(led.counts[rung], n, `counts.${rung} is right`);
  }
});

test("every concept in the registry has a figure — ideas are visible, not hidden", () => {
  // The point of the ladder is that an idea sits in the same catalog as the
  // shipping devices, drawn from the same camera, honestly marked. A concept
  // with no figure is one that quietly fell off the roadmap.
  const concepts = registry.devices.filter((d) => d.kind === "concept");
  for (const d of concepts) {
    const f = byId.get(`device.${d.id}`);
    assert.ok(f, `${d.id} is a concept with no figure — add it to CONCEPT_MASSING`);
    assert.strictEqual(f.confidence, "idea", `${d.id} renders on the idea rung`);
    assert.ok(f.sketch_note, `${d.id}'s sketch says what shape it is guessing at`);
  }
});

test("the on-glass art tier covers every id the firmware can resolve, at the same rev", () => {
  // fleet_figures_art.h is the display firmware's copy of the glyph tier —
  // pre-triangulated so an ESP32 never carries a tessellator. Its contract
  // (also pinned host-side by firmware/tests_host/test_fleet_figures_art.cpp,
  // but THIS suite is the gate canary-local.yml actually runs on a figures
  // change): every id the kFigures/kHardware lookups can return has art, at
  // the exact rev the lookup carries — a device that names itself must never
  // draw nothing, or stale art.
  const lookups = readFileSync(join(REPO, "firmware/common/core/fleet_figures.h"), "utf8");
  const art = readFileSync(join(REPO, "firmware/common/core/fleet_figures_art.h"), "utf8");

  const artRows = new Map(
    [...art.matchAll(/\{ "((?:device|part|board|tool)\.[^"]+)", "([0-9a-f]{8})", (\d+), kArt_\w+_faces \}/g)]
      .map((m) => [m[1], { rev: m[2], faces: Number(m[3]) }]),
  );
  assert.ok(artRows.size > 0, "the art table parses and is non-empty");

  const resolvable = [...lookups.matchAll(/\{ "[^"]+", "((?:device|part|board|tool)\.[^"]+)", "([0-9a-f]{8})", "(\w+)"/g)];
  assert.ok(resolvable.length > 0, "the lookup tables parse and are non-empty");
  for (const [, id, rev, confidence] of resolvable) {
    const row = artRows.get(id);
    assert.ok(row, `${id} is resolvable by the firmware but has no on-glass art`);
    assert.strictEqual(row.rev, rev, `${id}'s art rev matches its lookup rev`);
    assert.ok(row.faces > 0, `${id}'s art has faces to draw`);
    assert.notStrictEqual(confidence, "idea",
      `${id}: an idea must never be resolvable on-glass — ghosts are not drawn there`);
    // And the ledger agrees the drawing is current — three copies, one rev.
    const fig = byId.get(id);
    assert.ok(fig, `${id} exists in the ledger`);
    assert.strictEqual(fig.rev, rev, `${id}'s ledger rev matches the firmware's`);
  }

  // Geometry stays inside the declared box: coordinates are quarter-units of
  // the 64-unit glyph, so every value sits in [0, 256]. A vertex outside the
  // box would draw over a neighboring row on the glass.
  const scale = art.match(/kFigureArtScale = (\d+)/);
  assert.ok(scale && Number(scale[1]) === 256, "the art scale is the glyph's 64 * 4");
  for (const m of art.matchAll(/inline constexpr int16_t kArt_\w+_t\d+\[\] = \{([-\d,]+)\};/g)) {
    for (const v of m[1].split(",").map(Number)) {
      assert.ok(v >= 0 && v <= 256, `art coordinate ${v} escapes the 64-unit glyph box`);
    }
  }
});

// ---------------------------------------------------------------------------
// The one accent, pinned to the one registry. The figure palette (iso.mjs
// MATERIALS) deliberately draws a neutral drawing-style body — a technical
// drawing is not a product render — but its ACCENT claims to be the canary
// ink, and that claim used to be an independent literal nothing kept equal
// to the colorway registry (canary_color_lib.scad's CW_REGISTRY). Three
// yellows had already accumulated across the ecosystem. This pins the
// drawing accent to the registry's graphite-colorway ink, so a registry
// change goes red here instead of forking a fourth yellow.
// ---------------------------------------------------------------------------
test("the figure palette's accent IS the colorway registry's ink", () => {
  const iso = readFileSync(join(__dirname, "../tools/figures/iso.mjs"), "utf8");
  const acc = iso.match(/accent:\s*\{\s*base:\s*\[0x([0-9a-f]{2}),\s*0x([0-9a-f]{2}),\s*0x([0-9a-f]{2})\]/);
  assert.ok(acc, "iso.mjs declares the accent material as a hex byte triple");
  const lib = readFileSync(
    join(__dirname, "../../docs/hardware/enclosure/canary_color_lib.scad"), "utf8");
  const graphite = lib.match(/\["graphite",\s*"[^"]+",\s*"([0-9a-f]{6})",\s*"([0-9a-f]{6})"/);
  assert.ok(graphite, "canary_color_lib.scad declares the graphite colorway");
  assert.strictEqual(acc.slice(1, 4).join(""), graphite[2],
    "iso.mjs accent must equal CW_REGISTRY graphite ink — one yellow, one registry");
});
